%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;
[GP_FFCutsFits,FileResName] = recover_selected_cuts('GP_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

fit_res_field = 'all_fit_par';
separate_fig  = false; % if true, detach figures from live script
%%

[S_op11Ei200,J_op11Ei200,Gam_op11Ei200,S_op11Ei200q] = extract_fit_par( ...
    GP_FFCutsFits.(['Ei200_off110GPminFF_',fit_res_field]));
[S_op11Ei400,J_op11Ei400,Gam_op11Ei400,S_op11Ei400q] = extract_fit_par( ...
    GP_FFCutsFits.(['Ei400_off110GPminFF_',fit_res_field]));
[S_op11Ei800,J_op11Ei800,Gam_op11Ei800,S_op11Ei800q] = extract_fit_par( ...
    GP_FFCutsFits.(['Ei800_off110GPminFF_',fit_res_field]));

proj110minFF = GP_FFCutsFits.Ei200_off110GPminFF.data.proj;


[S_maEi800,J_maEi800,Gam_maEi800,S_maEi800q] = extract_fit_par( ...
    GP_FFCutsFits.(['Ei800_off200GPmaxFF_',fit_res_field]));
proj200maxFF = GP_FFCutsFits.Ei200_off200GPmaxFF.data.proj;
[S_mdEi800,J_mdEi800,Gam_mdEi800,S_mdEi800q] = extract_fit_par( ...
    GP_FFCutsFits.(['Ei800_off110GPmaxFF_',fit_res_field]));


plot_fp(separate_fig,'min FF change for low dE max FF for Ei800', ... %[output:group:0e31819d] %[output:8ef00c7a] %[output:63518000] %[output:3566f8fb]
    [S_op11Ei200,S_op11Ei400,S_op11Ei800,S_mdEi800,S_maEi800], ... %[output:8ef00c7a] %[output:63518000] %[output:3566f8fb]
    [J_op11Ei200,J_op11Ei400,J_op11Ei800,J_mdEi800,J_maEi800], ... %[output:8ef00c7a] %[output:63518000] %[output:3566f8fb]
    [Gam_op11Ei200,Gam_op11Ei400,Gam_mdEi800,Gam_op11Ei800,Gam_maEi800]); %[output:group:0e31819d] %[output:8ef00c7a] %[output:63518000] %[output:3566f8fb]
%%
bg_dataGPEi200 = extract_bg_par(GP_FFCutsFits.(['Ei200_off110GPminFF_',fit_res_field]),1);
bg_dataGPEi400 = extract_bg_par(GP_FFCutsFits.(['Ei400_off110GPminFF_',fit_res_field]),1);
bg_dataGPEi800mi = extract_bg_par(GP_FFCutsFits.(['Ei800_off110GPminFF_',fit_res_field]),1);
bg_dataGPEi800md = extract_bg_par(GP_FFCutsFits.(['Ei800_off110GPmaxFF_',fit_res_field]),1);
bg_dataGPEi800ma = extract_bg_par(GP_FFCutsFits.(['Ei800_off200GPmaxFF_',fit_res_field]),1);

plot_fp(separate_fig,'background value for different Ei',[], ... %[output:group:981d7022] %[output:2956d259]
    [bg_dataGPEi200,bg_dataGPEi400,bg_dataGPEi800mi,bg_dataGPEi800md,bg_dataGPEi800ma]) %[output:group:981d7022] %[output:2956d259]
%%
[~,bg_dataGPEi200] = fit_IXDsBg_helper(bg_dataGPEi200,[],true,'g'); %[output:4b8d5359] %[output:058cd520]
[~,bg_dataGPEi400] = fit_IXDsBg_helper(bg_dataGPEi400,[65,140],true,'b'); %[output:92f06bf9] %[output:3d193812]
[~,bg_dataGPEi800mi] = fit_IXDsBg_helper(bg_dataGPEi800mi,[80,240],true,'r'); %[output:51a975a2] %[output:67724157]
[~,bg_dataGPEi800md] = fit_IXDsBg_helper(bg_dataGPEi800md,[80,255],true,'y'); %[output:4c16eef6] %[output:2eeab59c]
[~,bg_dataGPEi800ma] = fit_IXDsBg_helper(bg_dataGPEi800ma,[80,290],true,'k'); %[output:50ac6ad8] %[output:38df5920]
%%
spp.Ei200_off110GPminNbg = GP_FFCutsFits.Ei200_off110GPminFF - ...
    sqw_eval(GP_FFCutsFits.Ei200_off110GPminFF,@linterp_bg,bg_dataGPEi200);
plot(spp.Ei200_off110GPminNbg); lz 0 1; keep_figure %[output:1d267f2f]

spp.Ei400_off110GPminNbg = GP_FFCutsFits.Ei400_off110GPminFF - ...
    sqw_eval(GP_FFCutsFits.Ei400_off110GPminFF,@linterp_bg,bg_dataGPEi400);
plot(spp.Ei400_off110GPminNbg); lz 0 1; keep_figure %[output:4a5ef8be]

spp.Ei800_off110GPminNbg = GP_FFCutsFits.Ei800_off110GPminFF - ...
    sqw_eval(GP_FFCutsFits.Ei800_off110GPminFF,@linterp_bg,bg_dataGPEi800mi);
plot(spp.Ei800_off110GPminNbg); lz 0 1; keep_figure %[output:21b3d823]

spp.Ei800_off110GPmaxNbg = GP_FFCutsFits.Ei800_off110GPmaxFF - ...
    sqw_eval(GP_FFCutsFits.Ei800_off110GPmaxFF,@linterp_bg,bg_dataGPEi800md);
plot(spp.Ei800_off110GPmaxNbg); lz 0 0.5; keep_figure %[output:360e84de]

spp.Ei800_off200GPmaxNbg = GP_FFCutsFits.Ei800_off200GPmaxFF - ...
    sqw_eval(GP_FFCutsFits.Ei800_off200GPmaxFF,@linterp_bg,bg_dataGPEi800ma);
plot(spp.Ei800_off200GPmaxNbg); lz 0 0.1; keep_figure %[output:6a7db578]
%%
q0=0.38 %[control:slider:0927]{"position":[4,8]} %[output:84d9ff9d]

%q0=-0.475
%w1ei800dE = cut(spp.Ei800_off200GPmaxNbg,[q0-0.025,q0+0.025],[]);
%w1ei800dE = cut(spp.Ei800_off110GPminNbg,[q0-0.025,q0+0.025],[]); %[output:6577cfcf]
w1ei800dE = cut(spp.Ei800_off110GPmaxNbg,[q0-0.025,q0+0.025],[]);
plot(w1ei800dE) %[output:90d10678]

%%
cuts_rangesGP = containers.Map();
cuts_rangesGP('Ei200_off110GPminNbg')  = [0;110];
cuts_rangesGP('Ei400_off110GPminNbg') = [110;160];
cuts_rangesGP('Ei800_off110GPminNbg') = [160;230];
cuts_rangesGP('Ei800_off110GPmaxNbg') = [230;250];
cuts_rangesGP('Ei800_off200GPmaxNbg') = [250;460];

[w2,fh] = build_disp_in_dir_with_ds(spp,cuts_rangesGP,[0,0.005,0.5],false); %[output:8e0f3dbb] %[output:2093395c]
%data_ranges = cuts_rangesGP.values;
%data_ranges  = [data_ranges{:}];
%pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
%save('GP_0p5_0p5_0p5_dataMFF','pan_data');
fh.UserData = w2.data;
%%
gamma=10;Seff0=0.7917;

J0=39; J1=35;
correct_ff = 1;
gap = 0;    %
init_fg_param = [correct_ff,8,gamma,Seff0,  0,   J0, J1,  0,  0,  0];

kk = tobyfit(spp.Ei800_off200GPmaxNbg);
kk = kk.set_fun(@sqw_iron);
hkl_proj = spp.Ei800_off200GPmaxNbg.data.proj;

%init_fg_params = [coffect_ff,T,gamma,Seff, gap, J0, J1, J2, J3, J4];
free_sw_param  =  [0          0, 1   ,1   , 0,    1, 1,   0,  0,  0];

kk = kk.set_pin({init_fg_param,hkl_proj});
kk = kk.set_free(free_sw_param);


%kk = kk.set_bfun (@linear_bg1D); % set_bfun sets the background functions
%
%bg_param = init_bg_param(valid);
%kk = kk.set_bpin (bg_param);  % initial background constant and gradient
%kk = kk.set_bfree (bfree);

kk = kk.set_options('list',2);


[fit_obj,fit_par] = kk.fit(); %[output:8e7bff83] %[output:74bb272e]
%%

plot(spp.Ei800_off200GPmaxNbg); lz 0 0.1;keep_figure; %[output:569eea8e]
%plot(fit_obj); lz 0 0.1;keep_figure; %[output:950be307]
%[fit_obj,fit_par] = kk.simulate();
%%
if ~exist('magi','var')
    magi = MagneticIons();
end
sppCr.Ei200_off110GPminNbg= magi.correct_mag_ff(spp.Ei200_off110GPminNbg);
plot(sppCr.Ei200_off110GPminNbg); lz 0 2;keep_figure; %[output:76e25368]

sppCr.Ei400_off110GPminNbg = magi.correct_mag_ff(spp.Ei400_off110GPminNbg);
plot(sppCr.Ei400_off110GPminNbg); lz 0 2; keep_figure %[output:515e4bc4]

sppCr.Ei800_off110GPminNbg = magi.correct_mag_ff(spp.Ei800_off110GPminNbg);
plot(sppCr.Ei800_off110GPminNbg); lz 0 2; keep_figure %[output:552bc267]

sppCr.Ei800_off110GPmaxNbg = magi.correct_mag_ff(spp.Ei800_off110GPmaxNbg);
plot(sppCr.Ei800_off110GPmaxNbg); lz 0 2; keep_figure %[output:59475e3f]

sppCr.Ei800_off200GPmaxNbg = magi.correct_mag_ff(spp.Ei800_off200GPmaxNbg);
plot(sppCr.Ei800_off200GPmaxNbg); lz 0 2; keep_figure %[output:21e862d9]
%%

[w2,fh] = build_disp_in_dir_with_ds(sppCr,cuts_rangesGP,[0,0.005,0.5],false); %[output:3192a9ef] %[output:486800d7]

data_ranges = cuts_rangesGP.values;
data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
save('GP_0p5_0p5_0p5_dataMFF','pan_data');

